//
// DUST fee sponsorship: the client half, and the transaction introspection both halves share.
//
// A Midnight transaction pays its fee in DUST. DUST is shielded, non-transferable, generated by
// registered NIGHT and never held by a contract — so a participant who holds no NIGHT cannot
// transact at all, however legitimate the call. For a collateral registry that is fatal: a
// debtor acknowledging an invoice, or a supplier accepting a batch, is not a crypto user and
// will not be made to acquire and register NIGHT first.
//
// The official pattern (docs.midnight.network/guides/dust-sponsorship, reference implementation
// midnightntwrk/example-private-party) splits balancing by token kind:
//
//   user    (0 DUST)  prove -> balance ['shielded','unshielded'] -> sign -> finalize (BIND)
//                     -> hand the bound transaction over as hex
//   sponsor (DUST)    deserialize -> balance ['dust'] -> sign -> finalize -> submit
//
// Four properties make this safe, and all four are worth saying out loud in a demo:
//
//   1. The contract authenticates by secret knowledge, not by who paid. The sponsor's DUST buys
//      a block slot and nothing else — it grants no authority inside the circuit.
//   2. The user binds first. Only a bound `FinalizedTransaction` crosses the wire, so the
//      sponsor cannot add, remove or re-target a call.
//   3. The network rejects a modified transaction: the binding is cryptographic.
//   4. DUST cannot be extracted. It is non-transferable; the worst a hostile caller can do is
//      make the sponsor pay fees, which is what the allowlist and the rate limit are for.
//
// This module holds everything that is not Node-specific: the HTTP client, the wallet adapter
// that routes submission through a sponsor, and `describeTransaction`, which reads the contract
// calls back out of a serialized transaction. The service uses the same `describeTransaction`,
// because an allowlist that trusts a label the caller sent is not an allowlist.
import type {
  Binding,
  FinalizedTransaction,
  Proof,
  SignatureEnabled,
  TransactionId,
} from '@midnight-ntwrk/midnight-js-protocol/ledger';
import { Transaction } from '@midnight-ntwrk/midnight-js-protocol/ledger';
import { fromHex, hex } from '../bytes.js';
import type { WalletAdapter } from './providers.js';

/** Bumped when the wire shape changes; the service refuses a request it does not understand. */
export const SPONSOR_PROTOCOL_VERSION = 1;

/** Default path the service listens on and the client posts to. */
export const SPONSOR_PATH = '/v1/sponsor';

// ------------------------------------------------------------------------------- the wire shape

export interface SponsorRequest {
  protocol: number;
  /** The user's bound, proven, fee-less transaction, hex-encoded. */
  tx: string;
  /**
   * What the caller believes it is doing. Advisory only: the service derives the real entry
   * points from `tx` and refuses a mismatch, so this exists for logs and for a clearer error.
   */
  circuit?: string;
  /**
   * A label for the sponsor's log. Advisory only, and deliberately so: the service buckets its
   * rate limit on the presented API key or on the client's socket address, never on anything
   * the request body carries, because a client can rotate a field in its own body forever.
   */
  caller?: string;
}

export interface SponsorResponse {
  protocol: number;
  txId: string;
  /** DUST the sponsor paid, in SPECK, when it could compute it. */
  feeSpeck?: string;
  /** Entry points the service recognised and allowed. */
  circuits: string[];
  /** Contract the call was addressed to. */
  contractAddress?: string;
}

export interface SponsorErrorBody {
  protocol: number;
  error: string;
  code: SponsorRefusalCode;
  /** Seconds to wait before retrying, on a rate-limit refusal. */
  retryAfterSeconds?: number;
}

export type SponsorRefusalCode =
  | 'BAD_REQUEST'
  | 'UNSUPPORTED_PROTOCOL'
  | 'UNREADABLE_TRANSACTION'
  | 'NOT_A_CONTRACT_CALL'
  | 'CONTRACT_NOT_ALLOWED'
  | 'CIRCUIT_NOT_ALLOWED'
  | 'CIRCUIT_MISMATCH'
  | 'FEE_TOO_LARGE'
  | 'RATE_LIMITED'
  | 'UNAUTHORIZED'
  | 'SPONSOR_OUT_OF_DUST'
  | 'SUBMIT_FAILED';

export class SponsorError extends Error {
  readonly code: SponsorRefusalCode | 'TRANSPORT';
  readonly status?: number;
  readonly retryAfterSeconds?: number;

  constructor(
    message: string,
    code: SponsorRefusalCode | 'TRANSPORT',
    options: { status?: number; retryAfterSeconds?: number; cause?: unknown } = {},
  ) {
    super(message, { cause: options.cause });
    this.name = 'SponsorError';
    this.code = code;
    this.status = options.status;
    this.retryAfterSeconds = options.retryAfterSeconds;
  }
}

// --------------------------------------------------------------------- transaction introspection

/** One contract action read out of a transaction. */
export interface TransactionAction {
  kind: 'call' | 'deploy' | 'maintenance' | 'unknown';
  contractAddress?: string;
  /** Entry point as text, when it decodes to printable ASCII. Circuit names always do. */
  entryPoint?: string;
  /** Entry point as lower-case hex, always present for a call. */
  entryPointHex?: string;
}

export interface TransactionDescription {
  actions: TransactionAction[];
  /** Entry point names of every contract *call*, in order. */
  circuits: string[];
  /** Distinct contract addresses touched. */
  contracts: string[];
  /** True when the transaction contains a deploy or a maintenance update. */
  hasAdministrativeAction: boolean;
}

/** Decodes the ledger's entry-point encoding into a circuit name when it is printable ASCII. */
function entryPointName(value: Uint8Array | string): { text?: string; hexValue: string } {
  if (typeof value === 'string') {
    return { text: value, hexValue: hex(new TextEncoder().encode(value)) };
  }
  const hexValue = hex(value);
  // Circuit names are ASCII; the ledger pads or length-prefixes nothing we have seen, but strip
  // trailing NULs defensively rather than letting one into an allowlist comparison.
  const trimmed = value.subarray(0, value.findIndex((b) => b === 0) === -1 ? value.length : value.findIndex((b) => b === 0));
  const text = new TextDecoder('utf-8', { fatal: false }).decode(trimmed);
  const printable = text.length > 0 && /^[\x20-\x7e]+$/.test(text);
  return printable ? { text, hexValue } : { hexValue };
}

interface LedgerContractCall {
  address?: unknown;
  entryPoint?: unknown;
}

/**
 * Reads the contract actions out of a transaction.
 *
 * Structural rather than `instanceof`: the ledger classes come from a WASM module that a caller
 * may have loaded through a different specifier, and a failed `instanceof` would silently
 * classify a real call as `unknown` — which, for an allowlist, fails open. Tagging on the shape
 * of the object cannot do that.
 */
export function describeTransaction(tx: FinalizedTransaction): TransactionDescription {
  const actions: TransactionAction[] = [];
  const intents = (tx as unknown as { intents?: Map<number, { actions?: unknown[] }> }).intents;
  for (const intent of intents?.values() ?? []) {
    for (const action of intent.actions ?? []) {
      const candidate = action as LedgerContractCall & { initialState?: unknown; updates?: unknown };
      const address = typeof candidate.address === 'string' ? candidate.address : undefined;
      if (candidate.entryPoint !== undefined) {
        const { text, hexValue } = entryPointName(candidate.entryPoint as Uint8Array | string);
        actions.push({ kind: 'call', contractAddress: address, entryPoint: text, entryPointHex: hexValue });
      } else if (candidate.initialState !== undefined) {
        actions.push({ kind: 'deploy', contractAddress: address });
      } else if (candidate.updates !== undefined) {
        actions.push({ kind: 'maintenance', contractAddress: address });
      } else {
        actions.push({ kind: 'unknown', contractAddress: address });
      }
    }
  }
  return {
    actions,
    circuits: actions.filter((a) => a.kind === 'call').map((a) => a.entryPoint ?? `0x${a.entryPointHex ?? ''}`),
    contracts: [...new Set(actions.map((a) => a.contractAddress).filter((a): a is string => a !== undefined))],
    hasAdministrativeAction: actions.some((a) => a.kind === 'deploy' || a.kind === 'maintenance'),
  };
}

/** Deserializes the hex a user hands over. Throws `SponsorError('UNREADABLE_TRANSACTION')`. */
export function deserializeSponsoredTx(txHex: string): FinalizedTransaction {
  let bytes: Uint8Array;
  try {
    bytes = fromHex(txHex.startsWith('0x') ? txHex.slice(2) : txHex);
  } catch (cause) {
    throw new SponsorError('the transaction is not valid hex', 'UNREADABLE_TRANSACTION', { cause });
  }
  try {
    return Transaction.deserialize<SignatureEnabled, Proof, Binding>('signature', 'proof', 'binding', bytes);
  } catch (cause) {
    throw new SponsorError(
      'the transaction did not deserialize as a signed, proven, bound transaction. A sponsored ' +
        'transaction must already be bound by the user — balance it with ' +
        "tokenKindsToBalance ['shielded','unshielded'], sign it, then finalize it.",
      'UNREADABLE_TRANSACTION',
      { cause },
    );
  }
}

export const serializeSponsoredTx = (tx: FinalizedTransaction): string => hex(tx.serialize());

// ------------------------------------------------------------------------------------- the client

export interface SponsorClientOptions {
  /** Base URL of the sponsor, with or without the `/v1/sponsor` path. */
  endpoint: string;
  /** Sent as `Authorization: Bearer …` when the service is configured with API keys. */
  apiKey?: string;
  /** A label for the sponsor's log. It does not affect the rate limit; see `SponsorRequest`. */
  caller?: string;
  /** Milliseconds to wait for the sponsor. Proving already happened, so this is only network. */
  timeoutMs?: number;
  /** Injected for tests and for runtimes with no global `fetch`. */
  fetchImpl?: typeof fetch;
}

const sponsorUrl = (endpoint: string): string => {
  const trimmed = endpoint.replace(/\/+$/, '');
  return trimmed.endsWith(SPONSOR_PATH) ? trimmed : `${trimmed}${SPONSOR_PATH}`;
};

/** Hands a bound, fee-less transaction to a sponsor, which pays the DUST and submits it. */
export async function requestSponsorship(
  txHex: string,
  options: SponsorClientOptions & { circuit?: string },
): Promise<SponsorResponse> {
  const doFetch = options.fetchImpl ?? globalThis.fetch;
  if (!doFetch) throw new SponsorError('no fetch implementation is available', 'TRANSPORT');

  const body: SponsorRequest = {
    protocol: SPONSOR_PROTOCOL_VERSION,
    tx: txHex,
    circuit: options.circuit,
    caller: options.caller,
  };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 120_000);
  let response: Response;
  try {
    response = await doFetch(sponsorUrl(options.endpoint), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(options.apiKey ? { Authorization: `Bearer ${options.apiKey}` } : {}),
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (cause) {
    throw new SponsorError(`could not reach the sponsor at ${options.endpoint}`, 'TRANSPORT', { cause });
  } finally {
    clearTimeout(timer);
  }

  const text = await response.text();
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new SponsorError(
      `the sponsor answered ${response.status} with a body that is not JSON: ${text.slice(0, 200)}`,
      'TRANSPORT',
      { status: response.status },
    );
  }

  if (!response.ok) {
    const error = parsed as SponsorErrorBody;
    throw new SponsorError(error.error ?? `the sponsor answered ${response.status}`, error.code ?? 'TRANSPORT', {
      status: response.status,
      retryAfterSeconds: error.retryAfterSeconds,
    });
  }
  return parsed as SponsorResponse;
}

// ------------------------------------------------------------------------------- wallet adapter

export interface SponsoredWalletOptions extends SponsorClientOptions {
  /** Called with what the sponsor reported, so a UI can show who paid and how much. */
  onSponsored?: (result: SponsorResponse) => void;
}

/**
 * Routes submission through a sponsor.
 *
 * Everything before submission is unchanged: the wrapped adapter still proves, balances and
 * binds, so the registry sees exactly the same transaction it would have seen from a funded
 * wallet. Only the last hop differs.
 *
 * The wrapped adapter must not pay DUST fees — a wallet that already balanced `['dust']` would
 * be paying twice and the sponsor's balancing would fail. Build it with
 * `createHeadlessWallet({ payDustFees: false })` or
 * `dappConnectorWalletAdapter(..., { payFees: false })`; both set `paysDustFees: false`, which
 * this checks.
 */
export function sponsoredWalletAdapter(inner: WalletAdapter, options: SponsoredWalletOptions): WalletAdapter {
  if (inner.paysDustFees !== false) {
    throw new Error(
      'sponsoredWalletAdapter needs a wallet that does not pay its own DUST fees. Create it with ' +
        'payDustFees: false (headless) or payFees: false (DApp connector), so that it balances ' +
        "only ['shielded','unshielded'] and leaves the fee to the sponsor.",
    );
  }
  return {
    ...inner,
    paysDustFees: false,
    async submitTx(tx): Promise<TransactionId> {
      const result = await requestSponsorship(serializeSponsoredTx(tx), options);
      options.onSponsored?.(result);
      return result.txId as TransactionId;
    },
  };
}
